public UserResponse fetchUserData(String userId) throws InterruptedException, ExecutionException {
    try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
        Supplier<Profile> profileTask = scope.fork(() -> profileService.fetch(userId));
        Supplier<List<Order>> ordersTask = scope.fork(() -> orderService.fetchForUser(userId));

        scope.join();
        scope.throwIfFailed();

        return new UserResponse(profileTask.get(), ordersTask.get());
    }
}
